sp_widget.client_script:
/**
 * Service Portal widget: "My Equipment Requests"  (Client Controller)
 * AngularJS controller; `c` is the controller instance referenced in the HTML template.
 */
api.controller = function($scope, spUtil) {
    var c = this;

    c.cancel = function(request) {
        if (!confirm('Cancel request ' + request.number + '?')) {
            return;
        }
        // c.server.get() sends this object as `input` to the server script,
        // then replaces c.data with the freshly loaded list.
        c.server.get({
            action: 'cancel',
            sys_id: request.sys_id
        }).then(function() {
            spUtil.addInfoMessage(c.data.message);
        });
    };

    c.stateClass = function(state) {
        switch (state) {
            case 'Approved':
            case 'Delivered':
                return 'label-success';
            case 'Pending Approval':
            case 'In Fulfilment':
                return 'label-warning';
            case 'Rejected':
            case 'Cancelled':
                return 'label-danger';
            default:
                return 'label-default';
        }
    };
};

sp_widget.script:
/**
 * Service Portal widget: "My Equipment Requests"  (Server Script)
 * Widget ID: eqreq_my_requests
 *
 * Runs on the server each time the widget loads or calls c.server.get/update.
 * `data` is sent to the client controller; `input` is what the client sent in.
 */
(function() {

    // ---- Handle actions sent from the client ----
    if (input && input.action === 'cancel' && input.sys_id) {
        var target = new GlideRecordSecure('x_2228927_equipm_0_request');   // honours ACLs
        if (target.get(input.sys_id) &&
            target.getValue('requested_for') === gs.getUserID() &&
            target.active.toString() === 'true') {
            target.setValue('state', '60');   // Cancelled; stock is released by the Business Rule
            target.work_notes = 'Cancelled from the portal.';
            target.update();
            data.message = 'Request ' + target.getValue('number') + ' cancelled.';
        } else {
            data.message = 'That request cannot be cancelled.';
        }
    }

    // ---- Load the list ----
    data.requests = [];
    var gr = new GlideRecordSecure('x_2228927_equipm_0_request');
    gr.addQuery('requested_for', gs.getUserID());
    gr.orderByDesc('sys_created_on');
    gr.setLimit(parseInt(options.limit, 10) || 10);   // instance option, default 10
    gr.query();

    while (gr.next()) {
        data.requests.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number'),
            equipment: gr.equipment.getDisplayValue(),
            quantity: parseInt(gr.getValue('quantity'), 10),
            total: gr.total_cost.getDisplayValue(),
            state: gr.state.getDisplayValue(),
            active: gr.active.toString() === 'true',
            created: gr.sys_created_on.getDisplayValue()
        });
    }

})();
